<div class="ami-panel"><div class="ami-panel-body"><h2 class="ami-section-title">Dashboard SPMI Auditee</h2><p class="text-muted">Ringkasan penugasan SPMI yang menjadi tanggung jawab Anda.</p><div class="row"><?php foreach (['assignments' => 'Penugasan', 'submissions_draft' => 'Submission Draft', 'submissions_submitted' => 'Submission Terkirim', 'due_soon' => 'Jatuh Tempo 7 Hari', 'overdue' => 'Terlambat'] as $key => $label): ?><div class="col-md-4 mb-3"><div class="ami-stat-card h-100"><div class="text-muted"><?php echo html_escape($label); ?></div><div class="h2 mb-0"><?php echo html_escape((string) $dashboard[$key]); ?></div></div></div><?php endforeach; ?></div><?php if ((int) $dashboard['assignments'] === 0): ?><div class="small text-muted">Belum ada penugasan SPMI untuk Anda.</div><?php endif; ?><section class="mt-4" aria-labelledby="auditee-notifications"><h3 id="auditee-notifications" class="ami-section-title">Notifikasi</h3><?php if (!$dashboard['notifications']): ?><div class="small text-muted">Belum ada notifikasi submission SPMI.</div><?php else: ?><div class="list-group"><?php foreach ($dashboard['notifications'] as $notification): ?><a class="list-group-item list-group-item-action" href="<?php echo site_url($notification['route']); ?>"><strong><?php echo html_escape($notification['title']); ?></strong><span class="badge badge-<?php echo html_escape($notification['severity']); ?> ml-2"><?php echo html_escape((string) $notification['count']); ?></span><div class="small text-muted"><?php echo html_escape($notification['detail']); ?></div></a><?php endforeach; ?></div><?php endif; ?></section></div></div>
